generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel ?avgAllocationPct ?avgReturnPct ?avgCurrentValue
WHERE {
  {
    SELECT ?seg ?segmentLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasSegment ?seg .
      ?seg rdfs:label ?segmentLabel .
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?seg ?segmentLabel
  }
  {
    SELECT ?seg (AVG(xsd:decimal(?returnPct)) AS ?avgReturnPct) (AVG(xsd:decimal(?currVal)) AS ?avgCurrentValue)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasSegment ?seg .
      ?inv wm:hasHolding ?hold .
      ?hold wm:returnsPct ?returnPct .
      ?hold wm:currentValue ?currVal .
    }
    GROUP BY ?seg
  }
}
ORDER BY ?segmentLabel

